css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .44); position: relative; display: flex; align-items: center; }
.loader .head { position: relative; width: calc(var(--loader-size) * .44); height: calc(var(--loader-size) * .44); flex: none; }
.loader .head::before, .loader .head::after { content: ''; position: absolute; left: 0; width: 100%; height: 50%; background: var(--accent); }
.loader .head::before { top: 0; border-radius: 100% 100% 0 0 / 200% 200% 0 0; transform-origin: 50% 100%; animation: jaw-top calc(var(--loader-speed) * .5) ease-in-out infinite; }
.loader .head::after { bottom: 0; border-radius: 0 0 100% 100% / 0 0 200% 200%; transform-origin: 50% 0%; animation: jaw-bottom calc(var(--loader-speed) * .5) ease-in-out infinite; }
.loader span { width: calc(var(--loader-size) * .1); height: calc(var(--loader-size) * .1); margin-left: calc(var(--loader-size) * .13); border-radius: 50%; background: var(--accent-2); animation: eat calc(var(--loader-speed) * 1.5) linear infinite; }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .5); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * 1); }
@keyframes jaw-top { 0%, 100% { transform: rotate(-38deg); } 50% { transform: rotate(0deg); } }
@keyframes jaw-bottom { 0%, 100% { transform: rotate(38deg); } 50% { transform: rotate(0deg); } }
@keyframes eat { 0% { transform: translateX(0); opacity: 1; } 100% { transform: translateX(calc(var(--loader-size) * -.2)); opacity: 0; } }
